let state={user:null,listings:[],category:"All",query:"",signupMode:false,profile:null,publicProfile:null,publicListing:null,reviews:[],canReview:false,hires:[],threads:[],activeThread:null,messages:[],workspace:"provider",messageChannel:null,notificationChannel:null,notifications:[]};

function safe(v=""){return String(v??"").replace(/[&<>"']/g,s=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[s]))}
function initials(name="User"){return name.split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join("").toUpperCase()||"U"}
function openModal(id){$(id)?.classList.remove("hidden");document.body.style.overflow="hidden"}
function closeModal(id){$(id)?.classList.add("hidden");$(id)?.classList.remove("show-threads");document.body.style.overflow=""}
function setAvatar(el,url,name){if(!el)return;el.innerHTML="";if(url){const img=document.createElement("img");img.src=url;img.alt=name||"Student";img.loading="lazy";img.onerror=()=>{el.innerHTML="";el.textContent=initials(name)};el.appendChild(img)}else el.textContent=initials(name)}
function fileToDataURL(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}
function profileName(){return state.profile?.full_name||state.user?.user_metadata?.full_name||state.user?.email?.split("@")[0]||"Student"}
function demoKey(prefix){return `campusx-${prefix}-${state.user?.id||"demo-user"}`}
function isUuid(v){return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(v||"")}
function requireLogin(message="Log in to continue."){if(state.user)return true;setAuthMode(false);$("authMsg").textContent=message;openModal("authModal");return false}

function applyTheme(theme){const value=theme==="dark"?"dark":"light";document.documentElement.dataset.theme=value;localStorage.setItem("campusx-theme",value);if($("themeIcon"))$("themeIcon").textContent=value==="dark"?"☀":"☾";if($("themeLabel"))$("themeLabel").textContent=value==="dark"?"Light":"Dark"}
function initTheme(){const saved=localStorage.getItem("campusx-theme");const preferred=saved||((window.matchMedia&&window.matchMedia("(prefers-color-scheme: dark)").matches)?"dark":"light");applyTheme(preferred)}
function extractEmail(v=""){const m=String(v||"").match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);return m?m[0].toLowerCase():""}

async function uploadProfileFile(file,folder){if(!sb||!state.user)return null;const ext=(file.name.split(".").pop()||"bin").toLowerCase();const path=`${state.user.id}/${folder}/${Date.now()}.${ext}`;const bucket=sb.storage.from("profile-files");const {error}=await bucket.upload(path,file,{upsert:true,contentType:file.type||undefined,cacheControl:"3600"});if(error){alert(`Photo upload failed: ${error.message}. Run the profile-files storage section in supabase-profile-upgrade.sql.`);return null}const {data}=bucket.getPublicUrl(path);return data?.publicUrl||null}
function demoPublicProfile(item){return{id:item.provider_id||item.student_name,full_name:item.student_name,university:"CampusX student provider",department:item.category,bio:item.description,skills:item.category,mobile:item.contact_info,email:item.contact_info?.includes("@")?item.contact_info.replace(/^.*Email:\s*/i,""):"",portfolio_url:"",avatar_url:"",cv_url:""}}

async function resolveCurrentProvider(){
  if(!sb||!state.publicListing||!isUuid(state.publicListing.id)) return state.publicProfile?.id||state.publicListing?.provider_id||null;
  if(isUuid(state.publicListing.provider_id)) return state.publicListing.provider_id;
  try{
    const {data,error}=await sb.rpc("resolve_legacy_listing_provider",{target_listing:state.publicListing.id});
    if(!error&&isUuid(data)){
      state.publicListing.provider_id=data;
      const local=state.listings.find(x=>String(x.id)===String(state.publicListing.id));
      if(local)local.provider_id=data;
      const {data:profile}=await sb.from("profiles").select("*").eq("id",data).maybeSingle();
      state.publicProfile={...demoPublicProfile(state.publicListing),...(profile||{}),id:data};
      renderPublicProfile();
      return data;
    }
  }catch(_){}
  return null;
}

async function openProvider(item,focusContact=false){state.publicListing=item;if(sb&&!isUuid(item.provider_id)&&isUuid(item.id)){try{const {data:resolved}=await sb.rpc("resolve_legacy_listing_provider",{target_listing:item.id});if(isUuid(resolved))item.provider_id=resolved}catch(_){}}let p=demoPublicProfile(item);if(sb){let data=null;const email=extractEmail(item.contact_info);if(item.provider_id){({data}=await sb.from("profiles").select("*").eq("id",item.provider_id).maybeSingle())}if(!data&&item.student_name){({data}=await sb.from("profiles").select("*").ilike("full_name",item.student_name.trim()).limit(1).maybeSingle())}if(!data&&email){({data}=await sb.from("profiles").select("*").ilike("email",email).limit(1).maybeSingle())}if(!data&&state.user){const mineByEmail=email&&state.user.email?.toLowerCase()===email;const mineByName=item.student_name?.trim().toLowerCase()===profileName().trim().toLowerCase();if(mineByEmail||mineByName)data={...state.profile,id:state.user.id,email:state.user.email||state.profile?.email||""}}if(data)p={...p,...data,id:data.id||item.provider_id||p.id}}else if(state.user&&(item.provider_id===state.user.id||item.student_name===state.profile?.full_name)){p={...p,...state.profile,id:state.user.id,email:state.user.email||state.profile?.email||""}}
state.publicProfile=p;$("feedPage").classList.add("hidden");$("profilePage").classList.add("hidden");$("providerPage").classList.remove("hidden");renderPublicProfile();await loadReviews();await checkReviewPermission();window.scrollTo({top:0,behavior:"smooth"});if(focusContact)setTimeout(()=>$("publicContact")?.scrollIntoView({behavior:"smooth",block:"center"}),180)}
function renderPublicProfile(){const p=state.publicProfile||{},item=state.publicListing||{},nm=p.full_name||item.student_name||"Student";$("publicName").textContent=nm;$("publicUniversity").textContent=[p.university,p.department].filter(Boolean).join(" • ")||"Student provider";$("publicBio").textContent=p.bio||item.description||"Student service provider.";$("publicSkills").textContent=p.skills?`Skills: ${p.skills}`:"";setAvatar($("publicAvatar"),p.avatar_url,nm);const contacts=[];if(p.mobile||p.contact_info)contacts.push(`<div><span class="text-white/35">Mobile / contact</span><div class="mt-1 font-bold">${safe(p.mobile||p.contact_info)}</div></div>`);if(p.email)contacts.push(`<div><span class="text-white/35">Email</span><div class="mt-1"><a class="font-bold text-violet-300" href="mailto:${safe(p.email)}">${safe(p.email)}</a></div></div>`);if(p.portfolio_url)contacts.push(`<div><span class="text-white/35">Portfolio</span><div class="mt-1"><a class="font-bold text-sky-300 hover:underline" target="_blank" rel="noopener" href="${safe(p.portfolio_url)}">Open portfolio ↗</a></div></div>`);$("publicContact").innerHTML=contacts.join("")||'<div class="text-white/40">No public contact details added yet. Use CampusX Messages instead.</div>';$("publicCV").innerHTML=p.cv_url?`<a class="inline-flex rounded-xl bg-sky-400/10 px-4 py-3 font-black text-sky-300" target="_blank" rel="noopener" href="${safe(p.cv_url)}">View CV / Resume ↗</a>`:"No CV uploaded yet.";$("hireName").textContent=nm}

async function loadReviews(){const key=state.publicProfile?.id||state.publicListing?.provider_id||state.publicListing?.student_name;if(sb&&isUuid(state.publicProfile?.id)){const {data}=await sb.from("profile_reviews").select("*").eq("profile_id",state.publicProfile.id).order("created_at",{ascending:false});state.reviews=data||[]}else state.reviews=JSON.parse(localStorage.getItem(`campusx-reviews-${key}`)||"[]");renderReviews()}
function renderReviews(){const rs=state.reviews||[],avg=rs.length?rs.reduce((a,b)=>a+Number(b.rating||0),0)/rs.length:0;$("publicRating").textContent=rs.length?`★ ${avg.toFixed(1)} · ${rs.length} review${rs.length===1?"":"s"}`:"★ New";$("experienceList").innerHTML=rs.length?rs.map(r=>`<div class="rounded-2xl border border-white/10 bg-white/[.04] p-4"><div class="font-black text-amber-200">${"★".repeat(Number(r.rating||0))}<span class="text-white/15">${"★".repeat(5-Number(r.rating||0))}</span></div><p class="mt-2 text-sm leading-6 text-white/55">${safe(r.message)}</p><div class="mt-2 text-xs text-white/25">${safe(r.reviewer_name||"Previous client")}</div></div>`).join(""):'<div class="rounded-2xl border border-dashed border-white/10 p-6 text-sm text-white/35">No client feedback yet.</div>'}
async function checkReviewPermission(){state.canReview=false;if(!state.user){updateReviewUI();return}const pid=state.publicProfile?.id||state.publicListing?.provider_id;if(String(state.user.id)===String(pid)){updateReviewUI("You cannot review your own provider profile.");return}if(sb&&isUuid(pid)){const {data,error}=await sb.from("hire_requests").select("id,status").eq("client_id",state.user.id).eq("provider_id",pid).eq("status","completed").limit(1);if(error)console.warn("Could not check completed hire:",error.message);state.canReview=!!data?.length}else{const hires=JSON.parse(localStorage.getItem(demoKey("hires"))||"[]");state.canReview=hires.some(h=>String(h.provider_key||h.provider_id)===String(pid)&&h.status==="completed")}updateReviewUI()}
function updateReviewUI(custom){const disabled=!state.canReview;$("reviewRating").disabled=disabled;$("reviewMessage").disabled=disabled;$("reviewSubmit").disabled=disabled;$("reviewSubmit").classList.toggle("opacity-40",disabled);$("reviewSubmit").classList.toggle("cursor-not-allowed",disabled);$("reviewHint").textContent=custom||(state.canReview?"Work marked complete — you can now leave feedback.":"Reviews unlock after the provider marks your hired work complete.")}

function renderFilters(){$("filters").innerHTML=CATEGORIES.map(c=>`<button data-cat="${safe(c)}" class="whitespace-nowrap rounded-full border px-4 py-2 text-sm font-black transition ${state.category===c?"border-violet-400/40 bg-violet-500 text-white":"border-white/10 bg-white/5 text-white/55 hover:bg-white/10"}">${safe(c)}</button>`).join("");document.querySelectorAll("[data-cat]").forEach(b=>b.onclick=()=>{state.category=b.dataset.cat;renderFilters();renderListings()})}
function filtered(){const q=state.query.trim().toLowerCase();return state.listings.filter(x=>(state.category==="All"||x.category===state.category)&&(!q||`${x.title} ${x.description} ${x.student_name} ${x.category}`.toLowerCase().includes(q)))}
function renderListings(){const items=filtered();$("count").textContent=`${items.length} active listing${items.length===1?"":"s"}`;$("grid").innerHTML=items.map((x,i)=>`<article class="skill-card cursor-pointer" data-id="${safe(x.id)}" style="animation-delay:${Math.min(i*50,300)}ms"><div class="flex items-start justify-between gap-3"><span class="rounded-full border border-violet-400/20 bg-violet-500/10 px-3 py-1 text-xs font-black text-violet-300">${safe(x.category)}</span><span class="text-xs text-white/25">${x.created_at?new Date(x.created_at).toLocaleDateString(undefined,{month:"short",day:"numeric"}):"New"}</span></div><h3 class="mt-5 text-xl font-black leading-snug">${safe(x.title)}</h3><p class="mt-3 line-clamp-3 text-sm leading-6 text-white/45">${safe(x.description)}</p><div class="mt-6 flex items-end justify-between gap-3 border-t border-white/10 pt-4"><div><div class="font-black">${safe(x.student_name)}</div><div class="mt-1 text-xs text-white/25">Student skill provider</div></div><div class="max-w-[45%] text-right text-sm font-black text-emerald-300">${safe(x.price)}</div></div><button data-id="${safe(x.id)}" class="contact mt-4 w-full rounded-xl border border-white/10 bg-white/5 p-3 text-sm font-black transition hover:bg-white hover:text-slate-950">View profile & contact</button></article>`).join("");document.querySelectorAll(".contact").forEach(b=>b.onclick=e=>{e.stopPropagation();const item=state.listings.find(x=>String(x.id)===b.dataset.id);if(item)openProvider(item,true)});document.querySelectorAll(".skill-card").forEach(card=>card.onclick=()=>{const item=state.listings.find(x=>String(x.id)===card.dataset.id);if(item)openProvider(item)});renderProfileListings()}
async function loadListings(){if(!sb){state.listings=[...demoListings];renderListings();return}const {data,error}=await sb.from("skill_listings").select("*").order("created_at",{ascending:false});state.listings=error?[...demoListings]:(data||[]);renderListings()}

function setAuthMode(signup){state.signupMode=signup;$("name").classList.toggle("hidden",!signup);$("authTitle").textContent=signup?"Create your student account":"Welcome back";$("authSubmit").textContent=signup?"Sign up":"Log in";$("loginTab").className=`flex-1 rounded-xl p-2.5 text-sm font-black ${!signup?"bg-white/10":"text-white/45"}`;$("signupTab").className=`flex-1 rounded-xl p-2.5 text-sm font-black ${signup?"bg-white/10":"text-white/45"}`}
function updateUser(user){state.user=user||null;const yes=!!user;document.body.classList.toggle("auth-required",!yes);$("login").classList.toggle("hidden",yes);$("signup").classList.toggle("hidden",yes);$("profileBtn").classList.toggle("hidden",!yes);$("profileBtn").classList.toggle("flex",yes);$("inboxBtn").classList.toggle("hidden",!yes);$("notificationWrap")?.classList.toggle("hidden",!yes);$("logout").classList.toggle("hidden",!yes);if(yes){closeModal("authModal");const nm=user.user_metadata?.full_name||user.email?.split("@")[0]||"Student";$("profileAvatarMini").textContent=initials(nm);$("studentName").value=nm;$("uniEmail").value=user.email||"";loadHires();loadInboxSummary();subscribeNotifications()}else{setAuthMode(false);openModal("authModal");state.notifications=[];renderNotifications();if(sb&&state.notificationChannel){sb.removeChannel(state.notificationChannel);state.notificationChannel=null}}}
async function loadProfile(){if(!state.user)return;const fallback={id:state.user.id||"demo",full_name:state.user.user_metadata?.full_name||state.user.email?.split("@")[0]||"Student",university:"",department:"",bio:"",skills:"",contact_info:"",mobile:"",portfolio_url:"",avatar_url:"",cv_url:"",email:state.user.email||""};if(!sb){state.profile={...fallback,...JSON.parse(localStorage.getItem("campusx-demo-profile")||"{}")};renderProfile();return}const {data,error}=await sb.from("profiles").select("*").eq("id",state.user.id).maybeSingle();if(error){console.warn("Could not load profile:",error.message);state.profile=fallback}else if(!data){const {data:created,error:createError}=await sb.from("profiles").upsert(fallback,{onConflict:"id"}).select().single();state.profile=createError?fallback:{...fallback,...created}}else state.profile={...fallback,...data,email:data.email||state.user.email||""};renderProfile();await claimLegacyListings()}
async function claimLegacyListings(){if(!sb||!state.user||!state.profile)return;try{await sb.rpc("claim_my_legacy_listings");const {data}=await sb.from("skill_listings").select("*").order("created_at",{ascending:false});if(data){state.listings=data;renderListings()}}catch(_){}}
function renderProfile(){const p=state.profile||{},nm=p.full_name||"Student";$("profileName").textContent=nm;$("profileUniversity").textContent=p.university||"University not added yet";$("profileBio").textContent=p.bio||"Add a short professional bio for clients.";$("profileEmail").textContent=p.email||state.user?.email||"—";$("profileDepartment").textContent=p.department||"—";$("profileMobile").textContent=p.mobile||p.contact_info||"—";$("profilePortfolio").innerHTML=p.portfolio_url?`<a class="text-violet-300 hover:underline" href="${safe(p.portfolio_url)}" target="_blank" rel="noopener">${safe(p.portfolio_url)}</a>`:"—";$("profileCV").innerHTML=p.cv_url?`<a class="text-sky-300 hover:underline" href="${safe(p.cv_url)}" target="_blank" rel="noopener">View / Download CV</a>`:"—";$("profileSkills").textContent=p.skills||"—";setAvatar($("profileAvatar"),p.avatar_url,nm);setAvatar($("profileAvatarMini"),p.avatar_url,nm);$("pfName").value=p.full_name||"";$("pfUniversity").value=p.university||"";$("pfDepartment").value=p.department||"";$("pfMobile").value=p.mobile||p.contact_info||"";$("pfPortfolio").value=p.portfolio_url||"";$("pfSkills").value=p.skills||"";$("pfBio").value=p.bio||"";renderProfileListings()}
function renderProfileListings(){if(!$("profileListings"))return;const email=(state.user?.email||"").toLowerCase(),name=(state.profile?.full_name||"").toLowerCase();let mine=state.listings.filter(x=>x.provider_id&&x.provider_id===state.user?.id);if(!mine.length)mine=state.listings.filter(x=>name&&x.student_name?.toLowerCase()===name);if(!mine.length&&email)mine=state.listings.filter(x=>x.contact_info?.toLowerCase().includes(email));$("profileListings").innerHTML=mine.length?mine.map(x=>`<div class="rounded-2xl border border-white/10 bg-white/[.04] p-4"><div class="flex items-start justify-between gap-3"><div><div class="font-black">${safe(x.title)}</div><div class="mt-1 text-xs text-white/35">${safe(x.category)}</div></div><div class="text-right"><div class="text-sm font-black text-emerald-300">${safe(x.price)}</div><button data-delete-skill="${safe(x.id)}" class="delete-skill-btn mt-3">Delete skill</button></div></div></div>`).join(""):'<div class="rounded-2xl border border-dashed border-white/10 p-8 text-center text-sm text-white/35">No provider listings yet.</div>';document.querySelectorAll("[data-delete-skill]").forEach(b=>b.onclick=()=>deleteSkill(b.dataset.deleteSkill))}
async function deleteSkill(id){if(!state.user)return;if(!confirm("Delete this skill listing? This cannot be undone."))return;const item=state.listings.find(x=>String(x.id)===String(id));if(!item)return;if(sb){if(item.provider_id!==state.user.id){await claimLegacyListings();const refreshed=state.listings.find(x=>String(x.id)===String(id));if(!refreshed||refreshed.provider_id!==state.user.id){alert("CampusX could not verify that this listing belongs to your account.");return}}const {error}=await sb.from("skill_listings").delete().eq("id",id).eq("provider_id",state.user.id);if(error){alert(error.message);return}}state.listings=state.listings.filter(x=>String(x.id)!==String(id));renderListings();renderProfileListings()}
function setWorkspace(mode){state.workspace=mode;const provider=mode==="provider";$("providerWorkspace").classList.toggle("hidden",!provider);$("clientWorkspace").classList.toggle("hidden",provider);$("providerTab").classList.toggle("active",provider);$("clientTab").classList.toggle("active",!provider);$("findMode").classList.toggle("active",!provider);$("offerMode").classList.toggle("active",provider)}
async function showProfile(mode="provider"){if(!requireLogin("Log in to open your CampusX dashboard."))return;$("feedPage").classList.add("hidden");$("providerPage").classList.add("hidden");$("profilePage").classList.remove("hidden");setWorkspace(mode);window.scrollTo({top:0,behavior:"smooth"});await loadProfile();await loadHires();await loadInboxSummary()}
function showFeed(){$("providerPage").classList.add("hidden");$("profilePage").classList.add("hidden");$("feedPage").classList.remove("hidden");$("findMode").classList.add("active");$("offerMode").classList.remove("active");window.scrollTo({top:0,behavior:"smooth"})}
async function saveProfile(e){e.preventDefault();if(!state.user)return;const payload={id:state.user.id,full_name:$("pfName").value.trim(),university:$("pfUniversity").value.trim(),department:$("pfDepartment").value.trim(),contact_info:$("pfMobile").value.trim(),mobile:$("pfMobile").value.trim(),portfolio_url:$("pfPortfolio").value.trim(),skills:$("pfSkills").value.trim(),bio:$("pfBio").value.trim(),email:state.user.email||"",updated_at:new Date().toISOString()};const picture=$("pfPicture").files[0],cv=$("pfCVFile").files[0];if(!sb){if(picture)payload.avatar_url=await fileToDataURL(picture);if(cv)payload.cv_url=await fileToDataURL(cv);localStorage.setItem("campusx-demo-profile",JSON.stringify(payload));state.profile={...state.profile,...payload}}else{if(picture){const up=await uploadProfileFile(picture,"avatars");if(up)payload.avatar_url=up}if(cv){const up=await uploadProfileFile(cv,"cvs");if(up)payload.cv_url=up}const {error}=await sb.from("profiles").upsert(payload,{onConflict:"id"});if(error){alert(error.message);return}await sb.auth.updateUser({data:{full_name:payload.full_name}});state.profile={...state.profile,...payload}}renderProfile();closeModal("editProfileModal")}

function openListing(){if(!requireLogin("Log in before publishing a provider skill."))return;if(state.user){$("studentName").value=state.profile?.full_name||profileName();$("uniEmail").value=state.user.email||"";$("contact").value=state.profile?.mobile||state.profile?.email||state.user.email||""}openModal("listingModal")}

async function openHire(){if(!requireLogin("Log in as a client student to send a hire request."))return;let pid=state.publicProfile?.id;if(sb&&!isUuid(pid))pid=await resolveCurrentProvider();if(state.user.id===pid){alert("You cannot hire your own provider profile.");return}$("hireTitle").value=state.publicListing?.title||"";$("hireDetails").value="";$("hireBudget").value=state.publicListing?.price||"";openModal("hireModal")}
async function submitHire(e){e.preventDefault();if(!requireLogin())return;let pid=state.publicProfile?.id;if(sb&&!isUuid(pid))pid=await resolveCurrentProvider();const linked=isUuid(pid);const row={provider_id:linked?pid:null,client_id:state.user.id,listing_id:isUuid(state.publicListing?.id)?state.publicListing.id:null,listing_title:state.publicListing?.title||$("hireTitle").value.trim(),provider_name:state.publicProfile?.full_name||state.publicListing?.student_name||"Provider",client_name:profileName(),request_title:$("hireTitle").value.trim(),details:$("hireDetails").value.trim(),budget:$("hireBudget").value.trim(),status:linked?"pending":"awaiting_provider_link",created_at:new Date().toISOString()};if(sb){const {error}=await sb.from("hire_requests").insert(row);if(error){alert(error.message);return}}else{const arr=JSON.parse(localStorage.getItem(demoKey("hires"))||"[]");arr.unshift({...row,id:crypto.randomUUID(),provider_key:pid});localStorage.setItem(demoKey("hires"),JSON.stringify(arr))}closeModal("hireModal");if(linked){alert("Hire request sent. You can message the provider from CampusX Messages.");await startConversation(true)}else{alert("Hire request saved. This legacy listing is not linked to a CampusX account yet; the request will attach automatically when the provider signs in and claims the listing. You can use the contact details on this profile in the meantime.")}await loadHires();await checkReviewPermission()}
async function loadHires(){if(!state.user)return;if(sb){const {data,error}=await sb.from("hire_requests").select("*").or(`client_id.eq.${state.user.id},provider_id.eq.${state.user.id}`).order("created_at",{ascending:false});if(error)console.warn("Could not load hire requests:",error.message);state.hires=data||[]}else state.hires=JSON.parse(localStorage.getItem(demoKey("hires"))||"[]");renderHires();renderHireInbox();await loadNotifications()}
function statusBadge(s){const map={pending:"text-amber-300 bg-amber-400/10",accepted:"text-sky-300 bg-sky-400/10",completed:"text-emerald-300 bg-emerald-400/10",declined:"text-rose-300 bg-rose-400/10",awaiting_provider_link:"text-violet-300 bg-violet-400/10"};return `<span class="rounded-full px-2.5 py-1 text-[10px] font-black uppercase ${map[s]||"text-white/50 bg-white/5"}">${safe(s)}</span>`}
