async function getOrCreateConversation(){if(!state.user)return null;let pid=state.publicProfile?.id;if(sb&&!isUuid(pid))pid=await resolveCurrentProvider();if(state.user.id===pid)return null;if(sb){if(!isUuid(pid)){alert("Direct CampusX messaging will activate as soon as this legacy listing is linked to its provider account. You can still send a hire request now, and use the provider contact details shown on the profile.");return null}const {data:found}=await sb.from("conversations").select("*").eq("provider_id",pid).eq("client_id",state.user.id).limit(1).maybeSingle();if(found)return found;const payload={provider_id:pid,client_id:state.user.id,listing_id:isUuid(state.publicListing?.id)?state.publicListing.id:null,provider_name:state.publicProfile?.full_name||state.publicListing?.student_name||"Provider",client_name:profileName(),listing_title:state.publicListing?.title||"CampusX conversation"};const {data,error}=await sb.from("conversations").insert(payload).select().single();if(error){alert(error.message);return null}return data}else{const key=demoKey("threads"),arr=JSON.parse(localStorage.getItem(key)||"[]");let t=arr.find(x=>x.provider_key===pid);if(!t){t={id:crypto.randomUUID(),provider_key:pid,provider_id:pid,client_id:state.user.id,provider_name:state.publicProfile?.full_name||"Provider",client_name:profileName(),listing_title:state.publicListing?.title||"CampusX conversation",created_at:new Date().toISOString()};arr.unshift(t);localStorage.setItem(key,JSON.stringify(arr))}return t}}
async function startConversation(silent=false){if(!requireLogin("Log in to message this student."))return;const t=await getOrCreateConversation();if(!t)return;state.activeThread=t;if(!silent){openModal("chatModal");await loadThreads();await openThread(t.id)}}
async function loadInboxSummary(){if(!state.user)return;if(sb){const {data}=await sb.from("conversations").select("*").or(`client_id.eq.${state.user.id},provider_id.eq.${state.user.id}`).order("updated_at",{ascending:false});state.threads=data||[]}else state.threads=JSON.parse(localStorage.getItem(demoKey("threads"))||"[]");$("inboxCount").textContent=state.threads.length;renderThreadPreviews();await loadNotifications()}
function renderThreadPreviews(){const top=state.threads.slice(0,4),html=top.length?top.map(t=>`<button data-thread-preview="${safe(t.id)}" class="rounded-xl border border-white/10 bg-white/[.04] p-3 text-left"><div class="font-black">${safe(otherName(t))}</div><div class="mt-1 truncate text-xs text-white/35">${safe(t.listing_title||"CampusX message")}</div></button>`).join(""):'<div class="rounded-xl border border-dashed border-white/10 p-5 text-sm text-white/35">No conversations yet.</div>';$("clientThreads").innerHTML=html;document.querySelectorAll("[data-thread-preview]").forEach(b=>b.onclick=()=>{openInbox().then(()=>openThread(b.dataset.threadPreview))})}
function otherName(t){return t.provider_id===state.user?.id?(t.client_name||"Client student"):(t.provider_name||"Provider student")}
function notificationSender(m){const t=state.threads.find(x=>String(x.id)===String(m.conversation_id));return t?otherName(t):(m.sender_name||m.client_name||m.provider_name||"CampusX student")}
function hireNotificationKey(h){return `campusx-hire-read-${state.user?.id||"guest"}-${h.id}`}
