async function loadNotifications(){if(!state.user)return;const notifications=[];if(sb){const threadIds=state.threads.map(t=>t.id).filter(Boolean);if(threadIds.length){const {data,error}=await sb.from("messages").select("id,conversation_id,sender_id,sender_name,body,message,created_at,read_at").in("conversation_id",threadIds).neq("sender_id",state.user.id).is("read_at",null).order("created_at",{ascending:false}).limit(20);if(!error)(data||[]).forEach(m=>notifications.push({...m,kind:"message"}))}}else{for(const t of state.threads){const arr=JSON.parse(localStorage.getItem(`campusx-messages-${t.id}`)||"[]");arr.filter(m=>m.sender_id!==state.user.id&&!m.read_at).forEach(m=>notifications.push({...m,kind:"message"}))}}(state.hires||[]).filter(h=>((String(h.provider_id)===String(state.user.id)&&["pending","accepted"].includes(h.status))||(String(h.client_id)===String(state.user.id)&&h.status==="completed"))&&!isHireNotificationRead(h)).forEach(h=>notifications.push({...h,kind:"hire"}));state.notifications=notifications.sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)).slice(0,20);renderNotifications()}
function renderNotifications(){const list=$("notificationList"),count=$("notificationCount");if(!list||!count)return;const n=state.notifications.length;count.textContent=n>99?"99+":String(n);count.classList.toggle("hidden",!n);list.innerHTML=n?state.notifications.map(m=>m.kind==="hire"?`<button class="notification-item" data-notif-hire="${safe(m.id)}"><div class="flex items-center justify-between gap-3"><span class="notif-name">Hiring update</span><span class="h-2 w-2 shrink-0 rounded-full bg-emerald-400"></span></div><div class="notif-text">${safe(m.provider_id===state.user?.id?`${m.client_name||"A client"} sent a hire request`:`Your work is ${m.status}`)}</div><div class="notif-time">${safe(m.created_at?new Date(m.created_at).toLocaleString():"")}</div></button>`:`<button class="notification-item" data-notif-thread="${safe(m.conversation_id)}"><div class="flex items-center justify-between gap-3"><span class="notif-name">${safe(notificationSender(m))}</span><span class="h-2 w-2 shrink-0 rounded-full bg-violet-400"></span></div><div class="notif-text">${safe(m.body||m.message||"New message")}</div><div class="notif-time">${safe(m.created_at?new Date(m.created_at).toLocaleString():"")}</div></button>`).join(""):'<div class="px-3 py-8 text-center text-xs text-white/35">You are all caught up.</div>';document.querySelectorAll("[data-notif-thread]").forEach(b=>b.onclick=async()=>{toggleNotificationMenu(false);await openInbox();await openThread(b.dataset.notifThread)});document.querySelectorAll("[data-notif-hire]").forEach(b=>b.onclick=async()=>{const h=state.notifications.find(x=>x.kind==="hire"&&String(x.id)===String(b.dataset.notifHire));markHireNotificationRead(h);state.notifications=state.notifications.filter(x=>x!==h);renderNotifications();toggleNotificationMenu(false);await openInbox();setInboxTab("hiring")})}
