async function markThreadRead(id){if(!state.user)return false;if(sb){const {error}=await sb.rpc("mark_conversation_messages_read",{target_conversation:id});if(error){console.warn("Could not mark conversation read:",error.message);return false}}else{const key=`campusx-messages-${id}`,arr=JSON.parse(localStorage.getItem(key)||"[]");arr.forEach(m=>{if(m.sender_id!==state.user.id)m.read_at=new Date().toISOString()});localStorage.setItem(key,JSON.stringify(arr))}state.notifications=state.notifications.filter(m=>String(m.conversation_id)!==String(id));renderNotifications();return true}
