function subscribeNotifications(){if(!sb||!state.user)return;if(state.notificationChannel)sb.removeChannel(state.notificationChannel);state.notificationChannel=sb.channel(`campusx-notifications-${state.user.id}`).on("postgres_changes",{event:"INSERT",schema:"public",table:"messages"},payload=>{if(payload.new.sender_id!==state.user.id){loadInboxSummary()}}).on("postgres_changes",{event:"DELETE",schema:"public",table:"messages"},()=>loadNotifications()).on("postgres_changes",{event:"INSERT",schema:"public",table:"hire_requests"},payload=>{if(String(payload.new.provider_id)===String(state.user.id)||String(payload.new.client_id)===String(state.user.id)){loadHires();loadInboxSummary()}}).on("postgres_changes",{event:"UPDATE",schema:"public",table:"hire_requests"},payload=>{if(String(payload.new.provider_id)===String(state.user.id)||String(payload.new.client_id)===String(state.user.id)){loadHires();loadInboxSummary()}}).subscribe()}
function renderHireInbox(){const box=$("hireInbox");if(!box)return;const relevant=state.hires.filter(h=>String(h.provider_id)===String(state.user?.id)||String(h.client_id)===String(state.user?.id));box.innerHTML=relevant.length?`${relevant.slice(0,5).map(h=>{const incoming=String(h.provider_id)===String(state.user.id);return `<div class="hire-inbox-card"><div class="hire-inbox-top"><b>${safe(incoming?h.client_name||"Client student":h.provider_name||"Provider student")}</b>${statusBadge(h.status)}</div><div class="hire-inbox-title">${safe(h.request_title||h.listing_title||"Hire request")}</div><div class="hire-inbox-details">${safe(h.details||"No project details added.")}</div><div class="hire-inbox-details">${safe(h.budget||"Budget not specified")}</div>${incoming&&h.status==="pending"?`<div class="hire-inbox-actions"><button data-hire-action="accepted" data-hire-id="${safe(h.id)}" class="button small secondary">Accept</button><button data-hire-action="declined" data-hire-id="${safe(h.id)}" class="button small ghost">Decline</button></div>`:incoming&&h.status==="accepted"?`<button data-hire-action="completed" data-hire-id="${safe(h.id)}" class="button small primary">Mark complete</button>`:h.status==="completed"&&!incoming?`<button data-review-hire-id="${safe(h.id)}" class="button small secondary">Leave feedback</button>`:""}</div>`}).join("")}`:"<div class=\"empty-state\">No hiring details yet.</div>";box.querySelectorAll("[data-hire-action]").forEach(b=>b.onclick=()=>updateHireStatus(b.dataset.hireId,b.dataset.hireAction));box.querySelectorAll("[data-review-hire-id]").forEach(b=>b.onclick=()=>openReviewForHire(state.hires.find(h=>String(h.id)===String(b.dataset.reviewHireId))))}
