async function openProviderForHire(h){if(!h)return;let listing=state.listings.find(x=>String(x.id)===String(h.listing_id));if(!listing)listing={id:h.listing_id||h.provider_id,title:h.listing_title||h.request_title,student_name:h.provider_name||"Provider student",provider_id:h.provider_id,description:h.details||"",price:h.budget||""};await openProvider(listing,false)}
async function loadThreads(){await loadInboxSummary();const previews={};if(sb&&state.threads.length){const {data}=await sb.from("messages").select("conversation_id,body,created_at,sender_id").in("conversation_id",state.threads.map(t=>t.id)).order("created_at",{ascending:false});const active=new Set((data||[]).map(m=>String(m.conversation_id)));(data||[]).forEach(m=>{if(!previews[m.conversation_id])previews[m.conversation_id]=m});state.threads=state.threads.filter(t=>active.has(String(t.id)))}else if(!sb){state.threads=state.threads.filter(t=>{const messages=JSON.parse(localStorage.getItem(`campusx-messages-${t.id}`)||"[]");if(messages.length)previews[t.id]=messages[messages.length-1];return messages.length})}await loadHires();renderHireInbox();$("threadList").innerHTML=state.threads.length?state.threads.map(t=>{const name=otherName(t),last=previews[t.id],preview=last?.body||"Start a conversation";return `<button data-thread-id="${safe(t.id)}" class="thread-item ${state.activeThread?.id===t.id?"active":""}"><span class="thread-avatar">${safe(initials(name))}<i></i></span><span class="thread-copy"><span class="thread-topline"><b>${safe(name)}</b><time>${safe(last?.created_at?new Date(last.created_at).toLocaleDateString(undefined,{month:"short",day:"numeric"}):"")}</time></span><span class="thread-preview">${safe(preview)}</span><span class="thread-context">${safe(t.listing_title||"CampusX conversation")}</span></span></button>`}).join(""):'<div class="thread-empty"><span class="thread-empty-icon">✉</span><b>No messages yet</b><span>Start a conversation from a student profile.</span></div>';document.querySelectorAll("[data-thread-id]").forEach(b=>b.onclick=()=>openThread(b.dataset.threadId))}
async function openInbox(){if(!requireLogin("Log in to open messages."))return;toggleNotificationMenu(false);openModal("chatModal");const mobile=window.matchMedia("(max-width: 699px)").matches;if(mobile){setInboxTab("messages");$("chatModal").classList.add("show-threads")}await loadThreads();if(!mobile&&(state.activeThread||state.threads[0]))await openThread((state.activeThread||state.threads[0]).id)}
async function openThread(id){const t=state.threads.find(x=>String(x.id)===String(id))||state.activeThread;if(!t)return;state.activeThread=t;$("chatHeader").textContent=`${otherName(t)} • ${t.listing_title||"CampusX"}`;$("chatModal").classList.remove("show-threads");$("messageForm").classList.remove("hidden");if(sb){const {data}=await sb.from("messages").select("*").eq("conversation_id",t.id).order("created_at",{ascending:true});state.messages=data||[]}else state.messages=JSON.parse(localStorage.getItem(`campusx-messages-${t.id}`)||"[]");renderMessages();await markThreadRead(t.id);await loadThreads();subscribeMessages(t.id)}
function renderMessages(){$("messageList").innerHTML=state.messages.length?state.messages.map(m=>`<div class="message-bubble ${m.sender_id===state.user?.id?"mine":""}">${m.sender_id===state.user?.id?`<div class="message-actions"><button class="delete-message-btn" data-delete-message="${safe(m.id)}" title="Delete message">Delete</button></div>`:""}<div class="pr-12">${safe(m.body||m.message||"")}</div><div class="message-sender">${safe(m.sender_name||notificationSender(m)||"Student")}</div></div>`).join(""):'<div class="grid h-full place-items-center text-sm text-white/30">Start the conversation.</div>';document.querySelectorAll("[data-delete-message]").forEach(b=>b.onclick=()=>deleteMessage(b.dataset.deleteMessage));$("messageList").scrollTop=$("messageList").scrollHeight}
async function deleteMessage(id){const m=state.messages.find(x=>String(x.id)===String(id));if(!m||String(m.sender_id)!==String(state.user?.id))return;if(!confirm("Delete this message permanently for both students?"))return;if(sb){let deleted=false;try{const {data,error}=await sb.rpc("delete_own_message",{target_message:String(id)});if(error)throw error;deleted=!!data}catch(err){alert(`Could not delete message: ${err.message||err}`);return}if(!deleted){alert("The message was not deleted. Run the latest CampusX SQL fix in Supabase, then try again.");await openThread(state.activeThread.id);return}const {data:check,error:checkError}=await sb.from("messages").select("id").eq("id",id).maybeSingle();if(checkError){alert(checkError.message);return}if(check){alert("Supabase still has this message, so it was not removed. Please run final-message-delete-fix.sql.");return}}else{const key=`campusx-messages-${state.activeThread.id}`;state.messages=state.messages.filter(x=>String(x.id)!==String(id));localStorage.setItem(key,JSON.stringify(state.messages))}state.messages=state.messages.filter(x=>String(x.id)!==String(id));renderMessages();await loadNotifications()}
function subscribeMessages(conversationId){if(!sb)return;if(state.messageChannel)sb.removeChannel(state.messageChannel);state.messageChannel=sb.channel(`messages-${conversationId}`).on("postgres_changes",{event:"INSERT",schema:"public",table:"messages",filter:`conversation_id=eq.${conversationId}`},payload=>{if(!state.messages.some(m=>m.id===payload.new.id)){state.messages.push(payload.new);renderMessages();if(payload.new.sender_id!==state.user?.id)markThreadRead(conversationId)}}).on("postgres_changes",{event:"DELETE",schema:"public",table:"messages",filter:`conversation_id=eq.${conversationId}`},payload=>{state.messages=state.messages.filter(m=>String(m.id)!==String(payload.old.id));renderMessages()}).subscribe()}
