$("listingForm").onsubmit=async e=>{e.preventDefault();if(!requireLogin())return;const payload={title:$("title").value.trim(),category:$("category").value,description:$("description").value.trim(),price:$("price").value.trim(),student_name:$("studentName").value.trim(),contact_info:$("contact").value.trim(),provider_id:state.user.id};if(sb&&state.user.email?.toLowerCase()!==$("uniEmail").value.trim().toLowerCase()){alert("University email must match your logged-in account.");return}if(sb){const {data,error}=await sb.from("skill_listings").insert(payload).select().single();if(error){alert(error.message);return}state.listings.unshift(data)}else state.listings.unshift({...payload,id:crypto.randomUUID(),created_at:new Date().toISOString()});e.target.reset();closeModal("listingModal");renderListings();showProfile("provider")};
function doSearch(v){state.query=v.toLowerCase();if($("search"))$("search").value=v;if($("searchMobile"))$("searchMobile").value=v;renderListings()}$("search").oninput=e=>doSearch(e.target.value);$("searchMobile").oninput=e=>doSearch(e.target.value);$("browseBtn").onclick=()=>$("marketplace").scrollIntoView({behavior:"smooth"});$("profileBtn").onclick=()=>showProfile("provider");$("homeBtn").onclick=$("backToFeed").onclick=$("backFromProvider").onclick=showFeed;$("offerMode").onclick=()=>showProfile("provider");$("findMode").onclick=showFeed;$("providerTab").onclick=()=>setWorkspace("provider");$("clientTab").onclick=()=>setWorkspace("client");$("editProfileBtn").onclick=()=>openModal("editProfileModal");$("profileForm").onsubmit=saveProfile;
$("hireProviderBtn").onclick=openHire;$("messageProviderBtn").onclick=()=>startConversation(false);$("hireForm").onsubmit=submitHire;$("messageForm").onsubmit=sendMessage;$("inboxBtn").onclick=openInbox;document.querySelectorAll("[data-open-inbox]").forEach(b=>b.onclick=openInbox);if($("notificationBtn"))$("notificationBtn").onclick=e=>{e.stopPropagation();toggleNotificationMenu()};if($("notificationOpenInbox"))$("notificationOpenInbox").onclick=openInbox;if($("markAllReadBtn"))$("markAllReadBtn").onclick=markAllNotificationsRead;document.addEventListener("click",e=>{if(!$("notificationWrap")?.contains(e.target))toggleNotificationMenu(false)});
$("mobileMenuBtn").onclick=e=>{e.stopPropagation();const menu=$("mobileMenu"),open=menu.classList.contains("hidden");menu.classList.toggle("hidden",!open);$("mobileMenuBtn").setAttribute("aria-expanded",String(open))};$("mobileMenuHome").onclick=()=>{closeMobileMenu();showFeed()};$("mobileMenuMessages").onclick=()=>{closeMobileMenu();openInbox()};$("mobileMenuProfile").onclick=()=>{closeMobileMenu();showProfile("provider")};$("mobileMenuLogout").onclick=()=>{closeMobileMenu();$("logout").click()};document.addEventListener("click",e=>{if(!$("mobileMenu")?.contains(e.target)&&e.target!==$("mobileMenuBtn"))closeMobileMenu()});function closeMobileMenu(){const menu=$("mobileMenu");if(menu){menu.classList.add("hidden");$("mobileMenuBtn")?.setAttribute("aria-expanded","false")}}
function setInboxTab(tab){const messages=tab==="messages";$("messagesTab")?.classList.toggle("active",messages);$("hiringTab")?.classList.toggle("active",!messages);$("messageInboxPanel")?.classList.toggle("hidden",!messages);$("hiringInboxPanel")?.classList.toggle("hidden",messages)}
$("messagesTab").onclick=()=>setInboxTab("messages");$("hiringTab").onclick=()=>setInboxTab("hiring");$("chatThreadsBtn").onclick=()=>{setInboxTab("messages");$("chatModal").classList.add("show-threads")};$("chatProfileBtn").onclick=()=>{if(state.activeThread?.provider_id&&String(state.activeThread.provider_id)!==String(state.user?.id)){const item=state.listings.find(x=>String(x.provider_id)===String(state.activeThread.provider_id));if(item)openProvider(item)}};
$("reviewForm").onsubmit=async e=>{e.preventDefault();if(!state.canReview){alert("Review unlocks after the provider marks the hired work complete.");return}const rating=Number($("reviewRating").value),message=$("reviewMessage").value.trim(),p=state.publicProfile||{},row={rating,message,reviewer_name:profileName(),created_at:new Date().toISOString()};if(sb&&isUuid(p.id)){const {error}=await sb.from("profile_reviews").insert({profile_id:p.id,reviewer_id:state.user.id,reviewer_name:profileName(),rating,message});if(error){alert(error.message);return}}else{const key=p.id||state.publicListing?.student_name,arr=JSON.parse(localStorage.getItem(`campusx-reviews-${key}`)||"[]");arr.unshift(row);localStorage.setItem(`campusx-reviews-${key}`,JSON.stringify(arr))}$("reviewMessage").value="";state.canReview=false;await loadReviews();updateReviewUI("Thanks — your review was added.")};
$("directReviewForm").onsubmit=async e=>{e.preventDefault();const h=state.reviewHire;if(!h||h.status!=="completed")return;const rating=Number($("directReviewRating").value),message=$("directReviewMessage").value.trim();if(!message)return;const row={rating,message,reviewer_name:profileName(),created_at:new Date().toISOString()};if(sb&&isUuid(h.provider_id)){const {error}=await sb.from("profile_reviews").insert({profile_id:h.provider_id,reviewer_id:state.user.id,reviewer_name:profileName(),rating,message});if(error){alert(`Could not submit feedback: ${error.message}`);return}}else{const key=h.provider_id||h.provider_name,arr=JSON.parse(localStorage.getItem(`campusx-reviews-${key}`)||"[]");arr.unshift(row);localStorage.setItem(`campusx-reviews-${key}`,JSON.stringify(arr))}closeModal("reviewModal");await loadHires();alert("Thanks — your feedback was added.")};
document.querySelectorAll("[data-close]").forEach(b=>b.onclick=()=>{closeModal("authModal");closeModal("listingModal")});document.querySelectorAll("[data-close-profile]").forEach(b=>b.onclick=()=>closeModal("editProfileModal"));document.querySelectorAll("[data-close-hire]").forEach(b=>b.onclick=()=>closeModal("hireModal"));document.querySelectorAll("[data-close-review]").forEach(b=>b.onclick=()=>closeModal("reviewModal"));document.querySelectorAll("[data-close-chat]").forEach(b=>b.onclick=()=>closeModal("chatModal"));document.querySelectorAll("[data-page-close]").forEach(b=>b.onclick=showFeed);document.querySelectorAll(".modal-backdrop").forEach(b=>b.onclick=()=>{["authModal","listingModal","editProfileModal","hireModal","reviewModal","chatModal"].forEach(closeModal)});
if(sb){sb.auth.getSession().then(async({data})=>{updateUser(data.session?.user||null);if(data.session?.user)await loadProfile()});sb.auth.onAuthStateChange(async(_,session)=>{updateUser(session?.user||null);if(session?.user)await loadProfile()})}
